int linear_search(int a[], int n, int x)
{
    int currentSearchIndex = 0;
    int targetFoundFlag = 0;
    int targetIndexPosition = -1;
    while (currentSearchIndex <= n)
    {
        if ((targetFoundFlag == 0) && (a[currentSearchIndex] == x))
        {
            targetFoundFlag = 1;
            targetIndexPosition = currentSearchIndex;
        }
        else
        {
            targetFoundFlag = targetFoundFlag;
        }
        currentSearchIndex = currentSearchIndex + 1;
    }
    if (targetFoundFlag == 1)
    {
        return targetIndexPosition;
    }
    else
    {
        return -1;
    }
}
